esDescriptionVersion":29,"default":false,"owner":"pan"}],"owner":"pan"},{"title":"Calibration","controls":[{"id":"display.spectrum.calOffset","label":"Cal Offset:","tooltip":"Cal Offset","kind":"decimal","binding":{"phone":"DisplayCalOffset"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan","default":0,"min":-30,"max":30,"step":0.5,"unit":"dB","decimals":1}],"owner":"pan"},{"title":"Readouts","controls":[{"id":"display.spectrumDefaults.showCursorFreq","label":"Cursor Freq","tooltip":"Display the frequency at the cursor position (always in MHz). Same toggle as the on-spectrum overlay-panel Cursor Freq button.","kind":"toggle","binding":{"phone":"DisplayShowCursorFreq"},"applies":"live","requiresDescriptionVersion":29,"default":true,"owner":"pan"},{"id":"display.gridScales.showFps","label":"FPS overlay","tooltip":"Show FPS reading in top left of spectrum area","kind":"toggle","binding":{"phone":"DisplayShowFps"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"}],"owner":"pan"},{"title":"Reset","controls":[{"id":"display.spectrumDefaults.smoothDefaults","label":"Reset to Smooth Defaults","tooltip":"Set the selected pan's spectrum and waterfall look to the NereusSDR smooth profile: Clarity Blue palette, log-recursive averaging with a 650 ms averaging time, a white trace without fill and a 30 ms waterfall update period. Manual waterfall levels become Auto; Clarity, Floor and Scale keep their modes. Under All pans every pan takes these changes. FFT size, frequency, band stack and per-band grid ranges are not affected.","kind":"button","binding":{"phone":"smoothDefaults"},"applies":"live","requiresDescriptionVersion":29,"confirm":"Set the selected Spectrum and Waterfall display settings to the NereusSDR smooth profile? Under All pans every pan takes these changes.\n\nManual waterfall levels become Auto; Clarity, Floor and Scale keep their modes. FFT size, frequency, band stack and per-band grid ranges are not affected.\n\nContinue?","owner":"pan"}],"owner":"pan","note":"It also sets Scheme and Rate on Waterfall and changes Manual waterfall levels to Auto on Levels."},{"title":"","controls":[{"id":"display.navigation.peaks","label":"Configure peaks →","tooltip":"Configure peaks →","kind":"button","binding":{"phone":"openDisplayPeaks"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone"},{"id":"display.navigation.multimeter","label":"Configure multimeter →","tooltip":"Configure multimeter →","kind":"button","binding":{"phone":"openDisplayMultimeter"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone"}]}]},{"id":"display.levels","title":"Levels","where":"mixed","sections":[{"title":"Spectrum scale","controls":[{"id":"display.levels.scaleMode","label":"Spectrum scale","tooltip":"Spectrum scale","kind":"choice","binding":{"phone":"DisplaySpectrumScaleMode"},"applies":"subscription","requiresDescriptionVersion":29,"owner":"pan","default":"Manual","options":[{"value":"Manual","label":"Manual"},{"value":"TrackFloor","label":"Track floor"}]},{"id":"display.gridScales.dbMax","label":"dB Max:","tooltip":"Signal level at the top of the display in dB, for the current band. Each band keeps its own value.","kind":"integer","binding":{"phone":"DisplayGridMax"},"applies":"live","requiresDescriptionVersion":29,"min":-200,"max":0,"step":1,"unit":"dBm","perBand":{"label":"dB Max (%1):"},"default":-40,"owner":"station","readout":"spectrumMax"},{"id":"display.gridScales.dbMin","label":"dB Min:","tooltip":"Signal level at the bottom of the display in dB, for the current band. Each band keeps its own value.","kind":"integer","binding":{"phone":"DisplayGridMin"},"applies":"live","requiresDescriptionVersion":29,"min":-200,"max":0,"step":1,"unit":"dBm","perBand":{"label":"dB Min (%1):"},"default":-140,"owner":"station","readout":"spectrumMin"},{"id":"display.gridScales.noiseFloorOffset","label":"Floor Offset:","tooltip":"Offset added to the noise floor estimate to compute the grid min. Use 