n":29,"owner":"pan","enabledWhen":{"phone":"DisplayWaterfallLevelsMode","oneOf":["Clarity"]}},{"id":"display.waterfallDefaults.copySpectrumMinMax","label":"Copy from spectrum scale","tooltip":"Copies the current spectrum display dB max and dB min values into the waterfall High Threshold and Low Threshold above.","kind":"button","binding":{"phone":"copySpectrumMinMax"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan"}],"owner":"pan"},{"title":"While transmitting","controls":[],"note":"A pan that transmits is drawn with the transmit scale and the transmit levels until it stops. Transmit Display →"}]},{"id":"display.waterfallDefaults","title":"Waterfall","where":"phone","sections":[{"title":"Drawing","controls":[{"id":"display.waterfallDefaults.colorScheme","label":"Scheme:","tooltip":"Waterfall color palette. Each scheme maps signal level to a different color gradient from low (dark) to high (bright).","kind":"choice","binding":{"phone":"DisplayWfColorScheme"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":0,"label":"Default"},{"value":1,"label":"Enhanced"},{"value":2,"label":"Spectran"},{"value":3,"label":"BlackWhite"},{"value":4,"label":"LinLog"},{"value":5,"label":"LinRad"},{"value":6,"label":"Custom"},{"value":7,"label":"Clarity Blue"}],"default":0,"owner":"pan"},{"id":"display.waterfall.customGradient","label":"Edit custom gradient...","tooltip":"Edit custom gradient...","kind":"button","binding":{"phone":"editReceiveGradient"},"applies":"subscription","requiresDescriptionVersion":29,"owner":"phone","editor":"receiveGradient","enabledWhen":{"phone":"DisplayWfColorScheme","oneOf":[6]}},{"id":"display.waterfallDefaults.updatePeriod","label":"Rate:","tooltip":"How often to update (scroll another pixel line) on the waterfall display.  Note that this is tamed by the FPS setting.","kind":"slider","binding":{"phone":"DisplayWfUpdatePeriodMs"},"applies":"subscription","requiresDescriptionVersion":29,"min":10,"max":500,"step":10,"unit":