,"options":[{"value":0,"label":"None"},{"value":1,"label":"Recursive"},{"value":2,"label":"Time Window"},{"value":3,"label":"Log Recursive"}],"default":0,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan"},{"id":"display.waterfallDefaults.averageTime","label":"WF Avg Time:","tooltip":"Waterfall averaging time constant. Independent from the spectrum averaging time. Larger = heavier smoothing. Translates to a frame-by-frame alpha via α = exp(−1 / (fps × τ)).","kind":"integer","binding":{"phone":"DisplayWaterfallAverageTimeMs"},"applies":"subscription","requiresDescriptionVersion":29,"min":1,"max":9999,"step":1,"unit":"ms","default":120,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayWaterfallAveraging","oneOf":[1,2,3,4]}}],"owner":"pan"},{"title":"Overlays","controls":[{"id":"display.waterfallDefaults.stopOnTx","label":"Stop on TX","tooltip":"Pause the waterfall while transmitting. Resumes automatically when TX ends.","kind":"toggle","binding":{"phone":"WaterfallStopOnTx"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"},{"id":"display.waterfallDefaults.showRxFilter","label":"RX Filter","tooltip":"Overlay the current RX passband filter boundaries on the waterfall display.","kind":"toggle","binding":{"phone":"DisplayShowRxFilterOnWaterfall"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"},{"id":"display.waterfallDefaults.showTxFilter","label":"TX Filter","tooltip":"Overlay the TX passband filter boundaries on the RX waterfall display.","kind":"toggle","binding":{"phone":"DisplayShowTxFilterOnRxWaterfall"},"applies":"live","requiresDescriptionVersion":29,"default":true,"owner":"pan"},{"id":"display.waterfallDefaults.showRxZeroLine","label":"RX Zero","tooltip":"Draw a line on the waterfall at the RX center frequency (zero-beat reference).","kind":"toggle","binding":{"phone":"DisplayShowRxZeroLine"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"},{"id":"display.waterfallDefaults.showTxZeroLine","label":"TX Zero","tooltip":"Draw a line on the waterfall at the TX center frequency (zero-beat reference).","kind":"toggle","binding":{"phone":"DisplayShowTxZeroLine"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"}],"owner":"pan"},{"title":"Time","controls":[{"id":"display.waterfallDefaults.timestampPosition","label":"Timestamp:","tooltip":"Position of the time stamp drawn on each waterfall row. None disables timestamps; Left and Right place them at the respective edge.","kind":"choice","binding":{"phone":"DisplayWfTimestampPos"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":0,"label":"None"},{"value":1,"label":"Left"},{"value":2,"label":"Right"}],"default":0,"owner":"pan"},{"id":"display.waterfallDefaults.timestampMode","label":"Time Zone:","tooltip":"Time zone used for waterfall timestamps. UTC uses Coordinated Universal Time; Local uses the system clock time zone.","kind":"choice","binding":{"phone":"DisplayWfTimestampMode"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":0,"label":"UTC"},{"value":1,"label":"Local"}],"default":0,"owner":"pan","enabledWhen":{"phone":"DisplayWfTimestampPos","oneOf":[1,2]}},{"id":"display.waterfallDefaults.historyDepth","label":"Rewind:","tooltip":"Maximum amount of waterfall history kept for rewind. Effective rewind is capped at 16384 rows; slow the update period to extend depth at fast refresh rates.","kind":"choice","binding":{"phone":"DisplayWaterfallHistoryMs"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":60000,"label":"60 seconds"},{"value":300000,"label":"5 minutes"},{"value":900000,"label":"15 minutes"},{"value":1200000,"label":"20 minutes"}],"default":1200000,"owner":"pan"}],"owner":"pan"}]},{"id":"display.threeD","title":"View","where":"phone","sections":[{"title":"View","controls":[{"id":"display.threeD.renderMode","label":"Spectrum:","tooltip":"2D: FFT trace + waterfall.\n3D: perspective stacked-trace spectrum stream.","kind":"choice","binding":{"phone":"DisplaySpectrumRenderMode"},"applies":"subscription","requiresDescriptionVersion":29,"options":[{"value":0,"label":"2D Waterfall"},{"value":1,"label":"3D Stacked Trace"}],"default":0,"gate":{"capability":"remoteMediaVersion","min":1},"owner":"pan"}],"owner":"pan"},{"title":"3D","controls":[{"id":"display.threeD.gain","label":"3D Gain:","tooltip":"3D surface color gain: how far down the signal range the colormap reaches.\nHigher = color down toward the noise floor; lower = color only on the strongest signals.","kind":"slider","binding":{"phone":"Display3DGain"},"applies":"live","requiresDescriptionVersion":29,"min":0,"max":100,"step":1,"unit":"%","default":70,"owner":"pan"},{"id":"display.threeD.span","label":"3D Span:","tooltip":"3D surface width: how far the nearest traces overhang the plot edges, using spectrum the radio sends from outside the panadapter.\nHigher = the empty wedges beside the surface close from the front; 0 = the classic narrowing trapezoid.","kind":"slider","binding":{"phone":"Display3DSpan"},"applies":"live","requiresDescriptionVersion":29,"min":0,"max":100,"step":1,"unit":"%","default":100,"owner":"pan"},{"id":"display.threeD.angle","label":"3D Angle:","tooltip":"Viewing angle for the 3D surface: low looks along the traces edge-on, high looks down on them.\n50 is the classic fixed angle.","kind":"slider","binding":{"phone":"Display3DAngle"},"applies":"live","requiresDescriptionVersion":29,"min":0,"max":100,"step":1,"unit":"%","default":50,"owner":"pan"},{"id":"display.view.speed","label":"3D Speed:","tooltip":"3D row cadence divider: Match follows the incoming frame rate; 1 to 10 draws one row per chosen number of frames.","kind":"slider","binding":{"phone":"Display3DSpeed"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan","default":0,"min":0,"max":10,"step":1},{"id":"display.threeD.sliceShadow","label":"3D Slice Shadow","tooltip":"Darken each slice's passband onto the 3D surface so it leans back\nwith the perspective, instead of drawing flat on top of it.","kind":"toggle","binding":{"phone":"Display3DSliceShadow"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"},{"id":"display.threeD.reset","label":"Reset 3D to defaults","tooltip":"Restore Spectrum render mode, 3D Floor, 3D Gain, 3D Span, 3D Angle, 3D Speed and 3D Slice Shadow to their ship defaults (2D Waterfall / 6 dB / 70% / 100% / 50% / Match / off).","kind":"button","binding":{"phone":"reset3d"},"applies":"live","requiresDescriptionVersion":29,"confirm":"This will restore Spectrum render mode, 3D Floor, 3D Gain, 3D Span, 3D Angle, 3D Speed and 3D Slice Shadow to their ship defaults.\n\nContinue?","owner":"pan"}],"owner":"pan"},{"title":"3D floor","controls":[{"id":"display.threeD.floor","label":"3D Floor:","tooltip":"How far below the noise floor the surface starts. Each band keeps its own value.","kind":"slider","binding":{"phone":"Display3DFloorDepth"},"applies":"live","requiresDescriptionVersion":29,"min":0,"max":24,"step":1,"unit":"dB","perBand":{"label":"3D Floor:"},"default":6,"owner":"pan"}],"owner":"pan"},{"title":"Background","controls":[{"id":"display.view.backgroundEnabled","label":"Background","tooltip":"Background","kind":"toggle","binding":{"phone":"DisplayBackgroundEnabled"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan","default":false},{"id":"display.view.backgroundColor","label":"BG Color:","tooltip":"BG Color","kind":"colour","binding":{"phone":"DisplayBackgroundColor"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan","default":"#0A0A14FF","enabledWhen":{"phone":"DisplayBackgroundEnabled","oneOf":[true]}},{"id":"display.view.backgroundImage","label":"Picture:","tooltip":"Choose a background picture for this pan. Choosing a picture turns the background on.","kind":"button","binding":{"phone":"chooseBackgroundImage"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan"},{"id":"display.view.clearBackgroundImage","label":"Clear picture","tooltip":"Clear picture","kind":"button","binding":{"phone":"clearBackgroundImage"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan"},{"id":"display.view.backgroundOpacity","label":"BG Opacity:","tooltip":"BG Opacity","kind":"slider","binding":{"phone":"DisplayBackgroundOpacity"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan","default":80,"min":0,"max":100,"step":1,"unit":"%","enabledWhen":{"phone":"DisplayBackgroundEnabled","oneOf":[true]}}],"owner":"pan"}]},{"id":"display.spectrumPeaks","title":"Peaks & Markers","where":"phone","sections":[{"title":"Peak trace","controls":[{"id":"display.spectrumPeaks.activePeakHold","label":"Peak trace with decay","tooltip":"Display a secondary trace of the highest recent level at each frequency bin. Each bin holds its peak for the hold duration after it was last raised, then falls at the drop rate.","kind":"toggle","binding":{"phone":"DisplayActivePeakHoldEnabled"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan"},{"id":"display.spectrumPeaks.activePeakHoldTime","label":"Hold:","tooltip":"How long (ms) a peak bin is held at its maximum before starting to decay.","kind":"integer","binding":{"phone":"DisplayActivePeakHoldDurationMs"},"applies":"subscription","requiresDescriptionVersion":29,"min":100,"max":60000,"step":100,"unit":"ms","default":2000,"gate":{"capability":"displayExtrasVersion","min":3},"owner":"pan","enabledWhen":{"phone":"DisplayActivePeakHoldEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.activePeakHoldDropRate","label":"Drop Rate:","tooltip":"Rate at which a held peak falls once its hold duration has passed.","kind":"integer","binding":{"phone":"DisplayActivePeakHoldDropDbPerSec"},"applies":"subscription","requiresDescriptionVersion":29,"min":1,"max":60,"step":1,"unit":"dB/s","default":6,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayActivePeakHoldEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.activePeakHoldFill","label":"Fill to trace","tooltip":"Shade the region between the live spectrum and the peak-hold trace.","kind":"toggle","binding":{"phone":"DisplayActivePeakHoldFill"},"applies":"live","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayActivePeakHoldEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.activePeakHoldOnTx","label":"Update during TX","tooltip":"Keep the peak trace running while this panadapter transmits. When off, the trace is hidden and paused until transmit ends.","kind":"toggle","binding":{"phone":"DisplayActivePeakHoldOnTx"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":3},"owner":"pan","enabledWhen":{"phone":"DisplayActivePeakHoldEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.activePeakHoldColor","label":"Peak Color:","tooltip":"Color of the dashed Active Peak Hold trace. Set this to a hue different from the live data-line color so the peak trace stays visible (e.g. after Reset to Smooth Defaults paints the live trace white).","kind":"colour","binding":{"phone":"DisplayActivePeakHoldColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#FFD700FF","gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayActivePeakHoldEnabled","oneOf":[true]}}],"owner":"pan"},{"title":"Peak markers","controls":[{"id":"display.spectrumPeaks.peakBlobs","label":"Peak markers","tooltip":"Display small circle markers at the top-N highest signal peaks in the spectrum.","kind":"toggle","binding":{"phone":"DisplayPeakBlobsEnabled"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan"},{"id":"display.spectrumPeaks.peakBlobCount","label":"Count:","tooltip":"Number of peak markers to display (1 to 20).","kind":"integer","binding":{"phone":"DisplayPeakBlobsCount"},"applies":"subscription","requiresDescriptionVersion":29,"min":1,"max":20,"step":1,"default":3,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.peakBlobInsideFilter","label":"Inside RX filter only","tooltip":"Restrict peak blobs to frequencies within the current RX filter passband.","kind":"toggle","binding":{"phone":"DisplayPeakBlobsInsideFilterOnly"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.peakBlobHold","label":"Hold before decay","tooltip":"Keep each blob at its peak position for the hold duration before falling.","kind":"toggle","binding":{"phone":"DisplayPeakBlobsHoldEnabled"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.peakBlobHoldTime","label":"Hold:","tooltip":"How long (ms) a blob is held at its peak before falling.","kind":"integer","binding":{"phone":"DisplayPeakBlobsHoldMs"},"applies":"subscription","requiresDescriptionVersion":29,"min":100,"max":60000,"step":100,"unit":"ms","default":500,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"allOf":[{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]},{"phone":"DisplayPeakBlobsHoldEnabled","oneOf":[true]}]}},{"id":"display.spectrumPeaks.peakBlobHoldDrop","label":"Decay after hold","tooltip":"When on, blobs decay at the fall rate after the hold. When off, blobs disappear instantly after the hold duration.","kind":"toggle","binding":{"phone":"DisplayPeakBlobsHoldDrop"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"allOf":[{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]},{"phone":"DisplayPeakBlobsHoldEnabled","oneOf":[true]}]}},{"id":"display.spectrumPeaks.peakBlobFallRate","label":"Fall Rate:","tooltip":"Rate at which blobs fall after the hold duration.","kind":"integer","binding":{"phone":"DisplayPeakBlobsFallDbPerSec"},"applies":"subscription","requiresDescriptionVersion":29,"min":1,"max":60,"step":1,"unit":"dB/s","default":6,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"allOf":[{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]},{"phone":"DisplayPeakBlobsHoldEnabled","oneOf":[true]},{"phone":"DisplayPeakBlobsHoldDrop","oneOf":[true]}]}},{"id":"display.spectrumPeaks.peakBlobColor","label":"Marker Color:","tooltip":"Color of the peak blob circles.","kind":"colour","binding":{"phone":"DisplayPeakBlobColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#FF4500FF","gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]}},{"id":"display.spectrumPeaks.peakBlobTextColor","label":"Text Color:","tooltip":"Color of the dBm readout text on each peak blob.","kind":"colour","binding":{"phone":"DisplayPeakBlobTextColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#7FFF00FF","gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayPeakBlobsEnabled","oneOf":[true]}}],"owner":"pan"},{"title":"Peak value","controls":[{"id":"display.spectrumDefaults.showPeakValue","label":"Peak Value","tooltip":"Display the peak signal level and frequency as a text overlay in the spectrum corner.","kind":"toggle","binding":{"phone":"DisplayShowPeakValueOverlay"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"},{"id":"display.spectrumDefaults.peakValuePosition","label":"Position:","tooltip":"Corner position for the peak value readout.","kind":"choice","binding":{"phone":"DisplayPeakValuePosition"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":0,"label":"Top Left"},{"value":1,"label":"Top Right"},{"value":2,"label":"Bottom Left"},{"value":3,"label":"Bottom Right"}],"default":1,"owner":"pan","enabledWhen":{"phone":"DisplayShowPeakValueOverlay","oneOf":[true]}},{"id":"display.spectrumDefaults.peakTextDelay","label":"Refresh:","tooltip":"Refresh interval for the peak value overlay in milliseconds.","kind":"integer","binding":{"phone":"DisplayPeakTextDelayMs"},"applies":"live","requiresDescriptionVersion":29,"min":50,"max":10000,"step":50,"unit":"ms","default":500,"owner":"pan","enabledWhen":{"phone":"DisplayShowPeakValueOverlay","oneOf":[true]}}],"owner":"pan"},{"title":"Noise floor line","controls":[{"id":"display.spectrumDefaults.showNoiseFloor","label":"Noise Floor","tooltip":"Display the noise floor as a horizontal dashed line + dBm box+text.","kind":"toggle","binding":{"phone":"DisplayShowNoiseFloor"},"applies":"subscription","requiresDescriptionVersion":29,"default":false,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan"},{"id":"display.spectrumDefaults.noiseFloorShift","label":"NF Shift:","tooltip":"Operator-tunable offset added to the rendered NF level, from -12 to +12 dB.","kind":"decimal","binding":{"phone":"DisplayNoiseFloorShiftDb"},"applies":"subscription","requiresDescriptionVersion":29,"min":-12,"max":12,"step":0.5,"decimals":1,"unit":"dB","default":0,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayShowNoiseFloor","oneOf":[true]}},{"id":"display.spectrumDefaults.noiseFloorLineWidth","label":"Line Width:","tooltip":"Width of the horizontal NF dashed line.","kind":"decimal","binding":{"phone":"DisplayNoiseFloorLineWidth"},"applies":"live","requiresDescriptionVersion":29,"min":1,"max":5,"step":0.5,"decimals":1,"unit":"px","default":1,"gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayShowNoiseFloor","oneOf":[true]}},{"id":"display.spectrumDefaults.noiseFloorColor","label":"Line Color:","tooltip":"Color for the NF line + 8x8 box.","kind":"colour","binding":{"phone":"DisplayNoiseFloorColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#FF40FFFF","gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayShowNoiseFloor","oneOf":[true]}},{"id":"display.spectrumDefaults.noiseFloorTextColor","label":"Text Color:","tooltip":"Color for the NF dBm label text.","kind":"colour","binding":{"phone":"DisplayNoiseFloorTextColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#FFFF00FF","gate":{"capability":"displayExtrasVersion","min":1},"owner":"pan","enabledWhen":{"phone":"DisplayShowNoiseFloor","oneOf":[true]}},{"id":"display.spectrumDefaults.noiseFloorFastColor","label":"Fast Attack:","tooltip":"Color shown during fast-attack (band/freq/MOX change).","kind":"colour","binding":{"phone":"DisplayNoiseFloorFastColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#C8C8C8FF","gate":{"capability":"displayExtrasVersion","min":4},"owner":"pan","enabledWhen":{"phone":"DisplayShowNoiseFloor","oneOf":[true]}},{"id":"display.peaksMarkers.noiseFloorPosition","label":"Text Position:","tooltip":"Text Position","kind":"choice","binding":{"phone":"DisplayShowNoiseFloorPosition"},"applies":"live","requiresDescriptionVersion":29,"owner":"pan","default":2,"options":[{"value":0,"label":"Top Left"},{"value":1,"label":"Top Right"},{"value":2,"label":"Bottom Left"},{"value":3,"label":"Bottom Right"}],"enabledWhen":{"phone":"DisplayShowNoiseFloor","oneOf":[true]},"availability":{"enabled":false,"reason":"Not used: the noise floor text sits beside its box. The setting is kept but has no visual effect."}}],"owner":"pan"},{"title":"Bin width","controls":[{"id":"display.spectrumDefaults.showBinWidth","label":"Bin Width","tooltip":"Display the current FFT bin width (sample rate / FFT size) in the spectrum corner.","kind":"toggle","binding":{"phone":"DisplayShowBinWidth"},"applies":"live","requiresDescriptionVersion":29,"default":false,"owner":"pan"}],"owner":"pan"},{"title":"","controls":[{"id":"display.navigation.spectrumFromPeaks","label":"← Spectrum","tooltip":"← Spectrum","kind":"button","binding":{"phone":"openDisplaySpectrum"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone"}]}]},{"id":"display.fftEngine","title":"FFT & Engine","where":"mixed","sections":[{"title":"FFT size","controls":[{"id":"display.spectrumDefaults.fftSizing","label":"Sizing","tooltip":"How the FFT size is chosen. Auto: the zoom picks the size to keep the picture sharp. Hz/bin: the size follows the bin width you set. Fixed: the FFT Size slider sets the size and zoom does not change it.","kind":"choice","binding":{"setting":"DisplayFftSizingMode"},"applies":"subscription","requiresDescriptionVersion":29,"options":[{"value":"Auto","label":"Auto"},{"value":"HzPerBin","label":"Hz/bin"},{"value":"Fixed","label":"Fixed"}],"default":"Auto","owner":"station"},{"id":"display.spectrumDefaults.fftSize","label":"FFT Size:","tooltip":"FFT size used for spectrum analysis. Range 4096 to 262144 in powers of two. Larger = finer frequency resolution and a smaller bin width, at higher CPU cost.","kind":"slider","binding":{"setting":"DisplayFftSize"},"applies":"subscription","requiresDescriptionVersion":29,"options":[{"value":4096,"label":"4096"},{"value":8192,"label":"8192"},{"value":16384,"label":"16384"},{"value":32768,"label":"32768"},{"value":65536,"label":"65536"},{"value":131072,"label":"131072"},{"value":262144,"label":"262144"}],"enabledWhen":{"setting":"DisplayFftSizingMode","oneOf":["Fixed"]},"default":4096,"owner":"station"},{"id":"display.spectrumDefaults.hzPerBinTarget","label":"Hz/bin:","tooltip":"The bin width to hold at every zoom. The FFT size follows it: sample rate divided by bin width, rounded up to a power of two, within the size limits.","kind":"decimal","binding":{"setting":"DisplayHzPerBinTarget"},"applies":"subscription","requiresDescriptionVersion":29,"min":0.5,"max":200,"step":0.5,"decimals":1,"unit":"Hz","enabledWhen":{"setting":"DisplayFftSizingMode","oneOf":["HzPerBin"]},"default":200,"owner":"station"},{"id":"display.spectrumDefaults.window","label":"Window:","tooltip":"FFT window function. Rectangular has the narrowest main lobe but the worst sidelobes. Blackman-Harris (4T or 7T) gives strong sidelobe rejection. Flat-Top is best for amplitude calibration. Kaiser is parameterized (Kaiser Pi shape parameter).","kind":"choice","binding":{"setting":"DisplayFftWindow"},"applies":"subscription","choices":["Rectangular","Blackman-Harris 4T","Hann","Flat-Top","Hamming","Kaiser","Blackman-Harris 7T"],"default":1,"requiresDescriptionVersion":29,"owner":"station"},{"id":"display.spectrumDefaults.decimation","label":"Decimation:","tooltip":"Display decimation. Higher the number, the lower the resolution.","kind":"integer","binding":{"phone":"decimation"},"applies":"subscription","requiresDescriptionVersion":29,"min":1,"max":16,"step":1,"default":1,"gate":{"capability":"spectrumGrantVersion","min":2},"owner":"station"}],"owner":"station"},{"title":"Frame rate","controls":[{"id":"display.spectrumDefaults.fps","label":"FPS:","tooltip":"Spectrum/waterfall redraw rate. Higher = smoother animation at cost of CPU.","kind":"slider","binding":{"setting":"DisplaySpectrumFps"},"applies":"subscription","min":10,"max":60,"step":1,"unit":"fps","default":30,"requiresDescriptionVersion":29,"owner":"station"},{"id":"display.spectrumDefaults.getMonitorHz","label":"Get Monitor Hz","tooltip":"Query the primary screen refresh rate and snap the FPS slider to the nearest valid value.","kind":"button","binding":{"phone":"getMonitorHz"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone"}],"owner":"station"},{"title":"This computer","controls":[{"id":"display.fftEngine.threadPriority","label":"Thread Priority:","tooltip":"Thread Priority","kind":"choice","binding":{"phone":"DisplayThreadPriority"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone","default":3,"options":[{"value":0,"label":"Lowest"},{"value":1,"label":"Below Normal"},{"value":2,"label":"Normal"},{"value":3,"label":"Above Normal"},{"value":4,"label":"Highest"}]}],"owner":"phone"}]},{"id":"display.txDisplay","title":"Transmit Display","where":"mixed","sections":[{"title":"FFT","controls":[{"id":"display.txDisplay.fftSize","label":"FFT Size:","tooltip":"TX FFT size used during MOX. Range 4096 to 262144 in powers of two. Larger gives finer frequency resolution and a smaller bin width at higher CPU cost. RX FFT slider is independent.","kind":"slider","binding":{"setting":"DisplayTxFftSize"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":4096,"label":"4096"},{"value":8192,"label":"8192"},{"value":16384,"label":"16384"},{"value":32768,"label":"32768"},{"value":65536,"label":"65536"},{"value":131072,"label":"131072"},{"value":262144,"label":"262144"}],"default":32768,"gate":{"capability":"txDisplayVersion","min":2},"owner":"station"},{"id":"display.txDisplay.window","label":"Window:","tooltip":"TX FFT window function. Hamming (default) trades a wide main lobe for moderate sidelobe rejection. Blackman-Harris (4T or 7T) gives strong sidelobe rejection for cleaner waterfall during TX. Flat-Top is best for amplitude calibration. Kaiser is parameterized.","kind":"choice","binding":{"setting":"DisplayTxWindowType"},"applies":"live","choices":["Rectangular","Blackman-Harris 4T","Hann","Flat-Top","Hamming","Kaiser","Blackman-Harris 7T"],"default":4,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"}],"owner":"station"},{"title":"Panadapter","controls":[{"id":"display.txDisplay.panDetector","label":"Detector:","tooltip":"TX panadapter trace detector. Peak shows the maximum bin value per pixel (transient-friendly). Average integrates across the bins (smoother). Sample takes one bin per pixel. RMS is true root-mean-square. Normalize is only available for Average / Sample / RMS.","kind":"choice","binding":{"setting":"DisplayTxPanDetector"},"applies":"live","choices":["Peak","Rosenfell","Average","Sample","RMS"],"default":0,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"},{"id":"display.txDisplay.panNormalize","label":"Normalize to 1 Hz","tooltip":"Normalize the TX panadapter trace to a 1 Hz reference bandwidth. Only available for the Average, Sample, and RMS detectors (the Peak and Rosenfell detectors are not power-like).","kind":"toggle","binding":{"setting":"DisplayTxPanNormalize"},"applies":"live","requiresDescriptionVersion":29,"default":false,"valueEncoding":{"true":"True","false":"False"},"enabledWhen":{"setting":"DisplayTxPanDetector","oneOf":["2","3","4"]},"gate":{"capability":"txDisplayVersion","min":2},"owner":"station"},{"id":"display.txDisplay.panAveraging","label":"Averaging:","tooltip":"TX panadapter trace averaging policy. None = instantaneous. Recursive = exponential smoothing with the time constant set below. Time Window = fixed-window N-frame average. Log Recursive = recursive in the log (dBm) domain.","kind":"choice","binding":{"setting":"DisplayTxPanAveraging"},"applies":"live","choices":["None","Recursive","Time Window","Log Recursive"],"default":0,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"},{"id":"display.txDisplay.panAvTime","label":"Avg Time:","tooltip":"TX panadapter averaging time constant in milliseconds. Larger values give smoother traces at the cost of slower response to transients.","kind":"integer","binding":{"setting":"DisplayTxPanAvTimeMs"},"applies":"live","min":1,"max":9999,"step":1,"unit":"ms","default":30,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"}],"owner":"station"},{"title":"Transmit scale","controls":[{"id":"display.transmit.scaleMax","label":"dB Max:","tooltip":"dB Max","kind":"slider","binding":{"phone":"DisplayTxGridRefLevel"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone","default":20,"min":-200,"max":200,"step":1,"unit":"dBm"},{"id":"display.transmit.scaleMin","label":"dB Min:","tooltip":"dB Min","kind":"slider","binding":{"phone":"DisplayTxGridMin"},"applies":"live","requiresDescriptionVersion":29,"owner":"phone","default":-80,"min":-200,"max":200,"step":1,"unit":"dBm"}],"owner":"phone"},{"title":"Waterfall","controls":[{"id":"display.txDisplay.wfDetector","label":"WF Detector:","tooltip":"TX waterfall detector. Applied independently of the pan detector. Peak suits transient visibility; Average gives a smoother waterfall floor.","kind":"choice","binding":{"setting":"DisplayTxWfDetector"},"applies":"live","choices":["Peak","Rosenfell","Average","Sample"],"default":0,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"},{"id":"display.txDisplay.wfAveraging","label":"WF Avg:","tooltip":"TX waterfall averaging policy. Applied independently of the pan averaging.","kind":"choice","binding":{"setting":"DisplayTxWfAveraging"},"applies":"live","choices":["None","Recursive","Time Window","Log Recursive"],"default":0,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"},{"id":"display.txDisplay.wfAvTime","label":"WF Avg Time:","tooltip":"TX waterfall averaging time constant in milliseconds. Defaults to 120 ms (longer than the pan default of 30 ms) so the waterfall preserves a longer time history.","kind":"integer","binding":{"setting":"DisplayTxWfAvTimeMs"},"applies":"live","min":1,"max":9999,"step":1,"unit":"ms","default":120,"gate":{"capability":"txDisplayVersion","min":2},"requiresDescriptionVersion":29,"owner":"station"}],"owner":"station"},{"title":"Waterfall Amplitude Scale","controls":[{"id":"display.txDisplay.wfLowLevel","label":"Low:","tooltip":"Waterfall Low Signal. Show Low Color below this value, with gradient in between.","kind":"integer","binding":{"phone":"DisplayTxWfLowLevel"},"applies":"live","requiresDescriptionVersion":29,"min":-200,"max":200,"step":5,"unit":"dBm","default":-70,"gate":{"capability":"txDisplayVersion","min":1},"owner":"phone"},{"id":"display.txDisplay.wfHighLevel","label":"High:","tooltip":"Waterfall High Signal. Show High Color above this value, with gradient in between.","kind":"integer","binding":{"phone":"DisplayTxWfHighLevel"},"applies":"live","requiresDescriptionVersion":29,"min":-200,"max":200,"step":5,"unit":"dBm","default":30,"gate":{"capability":"txDisplayVersion","min":1},"owner":"phone"},{"id":"display.txDisplay.wfPalette","label":"Palette:","tooltip":"Sets the color scheme for the TX waterfall.","kind":"choice","binding":{"phone":"DisplayTxWfPalette"},"applies":"live","requiresDescriptionVersion":29,"options":[{"value":1,"label":"Enhanced"},{"value":2,"label":"Spectran"},{"value":3,"label":"BlackWhite"},{"value":4,"label":"LinLog"},{"value":5,"label":"LinRad"},{"value":0,"label":"LinAuto"},{"value":6,"label":"Custom"}],"default":1,"gate":{"capability":"txDisplayVersion","min":1},"owner":"phone"},{"id":"display.txDisplay.wfLowColor","label":"Low Color:","tooltip":"Color used when the signal level is at or below the Low Level set above.","kind":"colour","binding":{"phone":"DisplayTxWfLowColor"},"applies":"live","requiresDescriptionVersion":29,"default":"#000000FF","gate":{"capability":"txDisplayVersion","min":1},"owner":"phone"},{"id":"display.transmit.customGradient","label":"Edit custom gradient...","tooltip":"Edit custom gradient...","kind":"button","binding":{"phone":"editTransmitGradient"},"applies":"subscription","requiresDescriptionVersion":29,"owner":"phone","editor":"transmitGradient","enabledWhen":{"phone":"D