        """#
        return (try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: [String: Any]]) ?? [:]
    }()

    nonisolated(unsafe) static let v29Rows: [String: [String: [String: Any]]] = v29Categories.mapValues { category in
        var rows: [String: [String: Any]] = [:]
        for page in category["pages"] as? [[String: Any]] ?? [] {
            for section in page["sections"] as? [[String: Any]] ?? [] {
                for row in section["controls"] as? [[String: Any]] ?? [] {
                    if let id = row["id"] as? String { rows[id] = row }
                }
            }
        }
        return rows
    }

    static func sameV29JSON(_ lhs: [String: Any], _ rhs: [String: Any]) -> Bool {
        guard let a = try? JSONSerialization.data(withJSONObject: lhs, options: [.sortedKeys]),
              let b = try? JSONSerialization.data(withJSONObject: rhs, options: [.sortedKeys]) else { return false }
        return a == b
    }

    // A section with no visible heading or no controls is admitted only
    // in its exact prescribed Display page position and shape.
    static func specialV29Section(_ raw: [String: Any], page: String) -> Bool {
        guard let pages = v29Categories["display"]?["pages"] as? [[String: Any]],
              let expected = pages.first(where: { $0["id"] as? String == page }),
              let sections = expected["sections"] as? [[String: Any]] else { return false }
        return sections.contains { expected in
            var expected = expected
            var actual = raw
            guard let rows = actual.removeValue(forKey: "controls") as? [[String: Any]],
                  let wanted = expected.removeValue(forKey: "controls") as? [[String: Any]] else { return false }
            // Row metadata is checked separately and stays unavailable when
            // corrupt; only identity/order belongs to the section envelope.
            return sameV29JSON(actual, expected)
                && rows.map({ $0["id"] as? String }) == wanted.map({ $0["id"] as? String })
        }
    }

    // Page and section structure is closed separately from row metadata:
    // a corrupt envelope rejects the category, a corrupt row stays unavailable.
    static func validV29Envelope(_ raw: [String: Any], category: String) -> Bool {
        guard var expected = v29Categories[category],
              let pages = raw["pages"] as? [[String: Any]],
              let wanted = expected["pages"] as? [[String: Any]], pages.count == wanted.count else { return false }
        for (index, page) in pages.enumerated() {
            var page = page
            var want = wanted[index]
            guard let sections = page.removeValue(forKey: "sections") as? [[String: Any]],
                  let desired = want.removeValue(forKey: "sections") as? [[String: Any]],
                  sameV29JSON(page, want), sections.count == desired.count else { return false }
            for (index, section) in sections.enumerated() {
                var section = section
                var want = desired[index]
                guard let rows = section.removeValue(forKey: "controls") as? [[String: Any]],
                      let wantedRows = want.removeValue(forKey: "controls") as? [[String: Any]],
                      sameV29JSON(section, want),
                      rows.map({ $0["id"] as? String }) == wantedRows.map({ $0["id"] as? String }) else { return false }
            }
        }
        var actual = raw
        actual.removeValue(forKey: "pages")
        expected.removeValue(forKey: "pages")
        return sameV29JSON(actual, expected)
    }

    static func parseV29Control(_ raw: [String: Any], id: String, label: String,
                               category: String, version: Int) -> Control {
        let exact = version == 29 && v29Rows[category]?[id].map { sameV29JSON(raw, $0) } == true
        let issue = exact ? nil : "Invalid closed V29 Setup metadata."
        let kind = (raw["kind"] as? String).flatMap(Kind.init(rawValue:))
        let binding = parseBinding(raw["binding"], id: id, kind: kind, version: version,
                                   columns: nil, rowActions: nil)
        var options: [Option]?
        var literals: [Int64: Literal] = [:]
        if let rawOptions = raw["options"] as? [[String: Any]] {
            options = rawOptions.enumerated().compactMap { index, option in
                guard let label = option["label"] as? String else { return nil }
                if let word = option["value"] as? String {
                    literals[Int64(index)] = .text(word)
                    return Option(value: Int64(index), label: label)
                }
                return integer(option["value"]).map { Option(value: $0, label: label) }
            }
        }
        let range: Range?
        if let minimum = number(raw["min"]), let maximum = number(raw["max"]), let step = number(raw["step"]) {
            // Keep the exact historical V29 wire step (10) for older phones, but let this phone edit Rate by 1 ms.
            let localStep = exact && category == "display" && id == "display.waterfallDefaults.updatePeriod" ? 1 : step
            range = Range(minimum: minimum, maximum: maximum, step: localStep)
        } else { range = nil }
        let gate: Gate?
        if let value = raw["gate"] as? [String: Any] {
            gate = Gate(capability: value["capability"] as? String, minimum: integer(value["min"]),
                        transmit: boolean(value["transmit"]), board: value["board"] as? String,
                        offAir: boolean(value["offAir"]))
        } else { gate = nil }
        let encoding: ValueEncoding?
        if let value = raw["valueEncoding"] as? [String: String], let yes = value["true"], let no = value["false"] {
            encoding = ValueEncoding(trueValue: yes, falseValue: no)
        } else { encoding = nil }
        func term(_ raw: [String: Any]) -> PhoneDependency? {
            guard let key = raw["phone"] as? String, let values = raw["oneOf"] as? [Any] else { return nil }
            return PhoneDependency(phone: key, oneOf: values.compactMap(literal))
        }
        let when = raw["enabledWhen"] as? [String: Any]
        let dependency: Dependency?
        if let key = when?["setting"] as? String, let values = when?["oneOf"] as? [String] {
            dependency = Dependency(setting: key, oneOf: values)
        } else { dependency = nil }
        let phoneDependency = when.flatMap(term)
        let allOf = (when?["allOf"] as? [[String: Any]])?.compactMap(term)
        var modern: Modern?
        if !literals.isEmpty { var value = Modern(); value.optionLiterals = literals; modern = value }
        let perBand = (raw["perBand"] as? [String: String])?["label"].map { PerBand(label: $0) }
        let availability: Availability?
        if let rawAvailability = raw["availability"] as? [String: Any],
           let enabled = boolean(rawAvailability["enabled"]), let reason = rawAvailability["reason"] as? String {
            availability = Availability(enabled: enabled, reason: reason)
        } else { availability = nil }
        return Control(id: id, label: label, tooltip: raw["tooltip"] as? String ?? "",
                       rawKind: raw["kind"] as? String ?? "", kind: kind, binding: binding,
                       applies: (raw["applies"] as? String).flatMap(Applies.init(rawValue:)),
                       range: range, unit: raw["unit"] as? String, choices: raw["choices"] as? [String],
                       decimals: integer(raw["decimals"]).map(Int.init), gate: gate, availability: availability,
                       valueEncoding: encoding, requiresDescriptionVersion: integer(raw["requiresDescriptionVersion"]).map(Int.init),
                       defaultValue: raw["default"].flatMap(literal), options: options,
                       enabledWhen: dependency, hygieneActions: nil, phoneDependency: phoneDependency,
                       perBand: perBand, confirm: raw["confirm"] as? String, metadataIssue: issue,
                       unavailableReason: issue, modern: modern, phoneAllOf: allOf,
                       owner: (raw["owner"] as? String).flatMap(DisplayOwner.init(rawValue:)),
                       editor: (raw["editor"] as? String).flatMap(GradientEditor.init(rawValue:)),
                       readout: (raw["readout"] as? String).flatMap(EffectiveReadout.init(rawValue:)))
    }
}
